{"PANIC","",{"I can't think! I can't think!","Oh, please, not now!","Somebody tell me what to do!","I want this to stop!","No, no, I wasn't ready for this!","I don't know what I'm doing!","Why can't I calm down?","Oh, hell. Oh, HELL!","Slow down! Everything, just slow down!","Don't leave me with this!","I can't get my head straight!","Please let me get through this!","I'm trying! I'm trying, all right?","God, I don't want to die!"}},
{"PANIC","reg=civilian,family,worker,rescue",{"Gunfire! Gunfire! Get down, get down!","Somebody's shooting! Run! RUN!","Get away! I don't want to die here!","Shots! That was a shot! Where's it coming from?","{He} has a knife! {He} has a knife!","Get away from me with that blade!","{He}'s got a bat! Stay away from {him}!","Don't swing that pipe at me!","{He}'s going to punch me! Somebody stop {him}!","{He}'s driving at us! Run!","{He}'s swinging it! Back up!","Get out! Everybody get out!","Don't let it catch me!"},false,false,false,{[1]="firearm",[2]="firearm",[4]="firearm",[5]="blade",[6]="blade",[7]="blunt",[8]="blunt",[9]="fists",[10]="vehicle",[11]="melee"}},
{"PANIC","reg=law",{"Shots fired! Take cover!","Be careful! Please, be careful!","Knife! Knife! Back up!","{He}'s got a crowbar! Back up and draw down on {him}!","Fall back! Fall back!"},false,false,false,{[1]="firearm",[3]="blade",[4]="blunt"}},
{"PANIC","reg=law,swat,military,elite",{"Taking fire! Get down!","This is bad! I need somewhere safer!","Blade! Keep your distance!","{He}'s swinging at us! Back away!"},false,false,false,{[1]="firearm",[3]="blade",[4]="melee"}},
